package net.officefloor.hq.app.pool;

import jakarta.validation.Valid;
import jakarta.validation.constraints.AssertTrue;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The pools of a sheet and their members. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/pools")
@Validated
public class PoolController {

    /** A member as shown: the person's id, or the member pool's id, and their share (two decimals). */
    public record PoolMemberView(Long personId, Long poolId, String share) {

        static PoolMemberView of(PoolMember m) {
            return new PoolMemberView(m.getPersonId(), m.getMemberPoolId(), m.getShare().toPlainString());
        }
    }

    /** A pool as shown, with its members in the order they were added. */
    public record PoolView(Long id, String name, List<PoolMemberView> members) {

        static PoolView of(Pool p) {
            return new PoolView(p.getId(), p.getName(), p.getMembers().stream().map(PoolMemberView::of).toList());
        }
    }

    /** The pool's name: surrounding spaces are removed, and it must not then be blank. */
    public record PoolRequest(@NotNull @NotBlank @Size(max = 255) String name) {
    }

    /**
     * A member to add: the person, or else another pool, and their share, more than 0.00 and at most 100.00, with at
     * most two decimals.
     */
    public record PoolMemberRequest(Long personId, Long poolId,
            @NotNull @Pattern(regexp = "\\s*\\d{1,3}(\\.\\d{1,2})?\\s*") String share) {

        @AssertTrue(message = "a member is a person or a pool")
        public boolean isOneMember() {
            return (personId == null) != (poolId == null);
        }
    }

    private final PoolService service;

    public PoolController(PoolService service) {
        this.service = service;
    }

    /** The sheet's pools, in the order they were added. */
    @GetMapping
    public List<PoolView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return service.list(sheetId.trim()).stream().map(PoolView::of).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PoolView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PoolRequest request) {
        return PoolView.of(service.add(sheetId.trim(), user.trim(), request.name().trim()));
    }

    @PostMapping("/{poolId}/members")
    @ResponseStatus(HttpStatus.CREATED)
    public PoolView addMember(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long poolId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PoolMemberRequest request) {
        BigDecimal share = new BigDecimal(request.share().trim());
        if (request.poolId() != null) {
            return PoolView.of(service.addMemberPool(sheetId.trim(), user.trim(), poolId, request.poolId(), share));
        }
        return PoolView.of(service.addMember(sheetId.trim(), user.trim(), poolId, request.personId(), share));
    }
}
package net.officefloor.hq.app.pool;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import java.util.ArrayList;
import java.util.List;

/** A pool on a sheet: people and other pools, each with a share percent. */
@Entity
@Table(name = "pool")
public class Pool {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The pool's members, in the order they were added. */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "pool_id", nullable = false)
    @OrderBy("id")
    private List<PoolMember> members = new ArrayList<>();

    protected Pool() {
    }

    public Pool(String sheetId, String name) {
        this.sheetId = sheetId;
        this.name = name;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public List<PoolMember> getMembers() {
        return members;
    }

    public boolean hasMember(Long personId) {
        return members.stream().anyMatch(m -> personId.equals(m.getPersonId()));
    }

    public boolean hasMemberPool(Long poolId) {
        return members.stream().anyMatch(m -> poolId.equals(m.getMemberPoolId()));
    }
}
package net.officefloor.hq.app.pool;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;

/** A member of a pool, with their share percent (two decimals): a person, or another pool. */
@Entity
@Table(name = "pool_member")
public class PoolMember {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** The person, or null when the member is a pool. */
    @Column(name = "person_id")
    private Long personId;

    /** The member pool, or null when the member is a person. */
    @Column(name = "member_pool_id")
    private Long memberPoolId;

    @Column(name = "share", nullable = false, precision = 5, scale = 2)
    private BigDecimal share;

    protected PoolMember() {
    }

    public PoolMember(Long personId, BigDecimal share) {
        this.personId = personId;
        this.share = share;
    }

    /** A pool as a member, with its share. */
    public static PoolMember ofPool(Long memberPoolId, BigDecimal share) {
        PoolMember m = new PoolMember(null, share);
        m.memberPoolId = memberPoolId;
        return m;
    }

    public Long getId() {
        return id;
    }

    public Long getPersonId() {
        return personId;
    }

    public Long getMemberPoolId() {
        return memberPoolId;
    }

    /** Make the membership another person's (a merge). */
    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public BigDecimal getShare() {
        return share;
    }

    public void setShare(BigDecimal share) {
        this.share = share;
    }
}
package net.officefloor.hq.app.pool;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** A pool, or a member of one, that may not be added. */
@ResponseStatus(HttpStatus.CONFLICT)
public class PoolRefusedException extends RuntimeException {

    public PoolRefusedException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.pool;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface PoolRepository extends JpaRepository<Pool, Long> {

    List<Pool> findBySheetIdOrderByIdAsc(String sheetId);

    Optional<Pool> findByIdAndSheetId(Long id, String sheetId);

    boolean existsBySheetIdAndName(String sheetId, String name);
}
package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Keeps the pools of a sheet, each name at most once, and their members: each person at most once in a pool, with a
 * share percent above 0.00 and at most 100.00. A person may be in several pools. A pool may be a member of another
 * pool, of at most one, never containing itself through any chain, and a chain of pools is at most three deep.
 */
@Service
public class PoolService {

    static final BigDecimal MAX_SHARE = new BigDecimal("100.00");

    /** The most pools in a chain of pools, each a member of the next. */
    static final int MAX_DEPTH = 3;

    private final PoolRepository pools;
    private final PersonRepository people;
    private final SheetRepository sheets;
    private final Audit audit;

    public PoolService(PoolRepository pools, PersonRepository people, SheetRepository sheets, Audit audit) {
        this.pools = pools;
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Pool> list(String sheetId) {
        return pools.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Add a pool by its name (already trimmed, not blank); refused when the sheet has one by that name. */
    @Transactional
    public Pool add(String sheetId, String user, String name) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException(sheetId);
        }
        if (pools.existsBySheetIdAndName(sheetId, name)) {
            throw new PoolRefusedException(name + " is already a pool on sheet " + sheetId);
        }
        Pool saved;
        try {
            saved = pools.saveAndFlush(new Pool(sheetId, name));
        } catch (DataIntegrityViolationException e) {
            throw new PoolRefusedException(name + " is already a pool on sheet " + sheetId);
        }
        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user + " name=" + saved.getName());
        return saved;
    }

    /** Add the person to the pool with the share (two decimals); refused when already in it or the share is out of range. */
    @Transactional
    public Pool addMember(String sheetId, String user, Long poolId, Long personId, BigDecimal share) {
        Pool pool = pools.findByIdAndSheetId(poolId, sheetId)
                .orElseThrow(() -> new PoolRefusedException("No pool " + poolId + " on sheet " + sheetId));
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, personId));
        if (share.scale() > 2 || share.signum() <= 0 || share.compareTo(MAX_SHARE) > 0) {
            throw new PoolRefusedException("A share is more than 0.00 and at most 100.00, with two decimals");
        }
        if (pool.hasMember(personId)) {
            throw new PoolRefusedException(person.getName() + " is already in pool " + pool.getName());
        }
        BigDecimal scaled = share.setScale(2);
        pool.getMembers().add(new PoolMember(personId, scaled));
        try {
            pools.saveAndFlush(pool);
        } catch (DataIntegrityViolationException e) {
            throw new PoolRefusedException(person.getName() + " is already in pool " + pool.getName());
        }
        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
                + " name=" + person.getName() + " share=" + scaled.toPlainString());
        return pool;
    }

    /**
     * Add another pool of the sheet to the pool as a member with the share (two decimals); refused when the share is out
     * of range, when the member is already in a pool, when the pool would then contain itself through any chain, or
     * when a chain of pools would then be more than three deep.
     */
    @Transactional
    public Pool addMemberPool(String sheetId, String user, Long poolId, Long memberPoolId, BigDecimal share) {
        Pool pool = pools.findByIdAndSheetId(poolId, sheetId)
                .orElseThrow(() -> new PoolRefusedException("No pool " + poolId + " on sheet " + sheetId));
        Pool member = pools.findByIdAndSheetId(memberPoolId, sheetId)
                .orElseThrow(() -> new PoolRefusedException("No pool " + memberPoolId + " on sheet " + sheetId));
        if (share.scale() > 2 || share.signum() <= 0 || share.compareTo(MAX_SHARE) > 0) {
            throw new PoolRefusedException("A share is more than 0.00 and at most 100.00, with two decimals");
        }
        List<Pool> all = pools.findBySheetIdOrderByIdAsc(sheetId);
        // Each pool that is a member of another, by the pool above it.
        Map<Long, Long> above = new HashMap<>();
        for (Pool p : all) {
            for (PoolMember m : p.getMembers()) {
                if (m.getMemberPoolId() != null) {
                    above.put(m.getMemberPoolId(), p.getId());
                }
            }
        }
        if (above.containsKey(memberPoolId)) {
            throw new PoolRefusedException(member.getName() + " is already a member of a pool");
        }
        // Levels from the top down to the pool (the pool itself counting one); a chain from the member back to the
        // pool would contain the pool in itself.
        int levels = 0;
        for (Long at = poolId; at != null; at = above.get(at)) {
            if (at.equals(memberPoolId)) {
                throw new PoolRefusedException(pool.getName() + " may not contain itself");
            }
            levels++;
        }
        if (levels + height(memberPoolId, all) > MAX_DEPTH) {
            throw new PoolRefusedException("A chain of pools is at most " + MAX_DEPTH + " deep");
        }
        BigDecimal scaled = share.setScale(2);
        pool.getMembers().add(PoolMember.ofPool(memberPoolId, scaled));
        try {
            pools.saveAndFlush(pool);
        } catch (DataIntegrityViolationException e) {
            throw new PoolRefusedException(member.getName() + " is already a member of a pool");
        }
        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
                + " name=" + member.getName() + " share=" + scaled.toPlainString());
        return pool;
    }

    /** The levels of pools from this one down its deepest chain of member pools, itself counting one. */
    private static int height(Long poolId, List<Pool> all) {
        Pool pool = all.stream().filter(p -> p.getId().equals(poolId)).findFirst().orElse(null);
        int below = 0;
        if (pool != null) {
            for (PoolMember m : pool.getMembers()) {
                if (m.getMemberPoolId() != null) {
                    below = Math.max(below, height(m.getMemberPoolId(), all));
                }
            }
        }
        return 1 + below;
    }
}
-- The pools of a sheet, each name at most once (kept trimmed).
CREATE TABLE pool (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(255) NOT NULL
);
CREATE UNIQUE INDEX pool_sheet_name ON pool (sheet_id, name);

-- The members of a pool, each person at most once, with their share percent (two decimals, above 0, at most 100).
CREATE TABLE pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id   BIGINT       NOT NULL REFERENCES pool (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    share     DECIMAL(5, 2) NOT NULL
);
CREATE UNIQUE INDEX pool_member_pool_person ON pool_member (pool_id, person_id);
-- A pool member may be another pool instead of a person: exactly one of person_id and member_pool_id is set. A pool is
-- a member of at most one pool; it has no pot of its own, its pot being its cut in the pool above.
